INSERT INTO `modx_site_plugins` VALUES (1,'CodeMirror','<strong>1.2b</strong> JavaScript library that can be used to create a relatively pleasant editor interface based on CodeMirrir 3.13',0,6,0,'$_CM_BASE = \'assets/plugins/codemirror/\';\n\n$_CM_URL = $modx->config[\'site_url\'] . $_CM_BASE;\n\nrequire(MODX_BASE_PATH. $_CM_BASE .\'codemirror.plugin.php\');\n\n',0,'&theme=Theme;list;default,ambiance,blackboard,cobalt,eclipse,elegant,erlang-dark,lesser-dark,midnight,monokai,neat,night,rubyblue,solarized,twilight,vibrant-ink,xq-dark,xq-light; &indentUnit=Indent unit;int;4 &tabSize=The width of a tab character;int;4 &lineWrapping=lineWrapping;list;true,false;true &matchBrackets=matchBrackets;list;true,false;false &activeLine=activeLine;list;true,false;false &emmet=emmet;list;true,false;true &search=search;list;true,false;true',1,'',0,0),(2,'FileSource','<strong>0.1</strong> Save snippet and plugins to file',0,6,0,'require MODX_BASE_PATH.\'assets/plugins/filesource/plugin.filesource.php\';',0,'',0,'',0,0),(3,'Forgot Manager Login','<strong>1.1.6</strong> Resets your manager login when you forget your password via email confirmation',0,6,0,'require MODX_BASE_PATH.\'assets/plugins/forgotmanagerlogin/plugin.forgotmanagerlogin.php\';\n',0,'',1,'',0,0),(4,'ManagerManager','<strong>0.3.11</strong> Customize the MODx Manager to offer bespoke admin functions for end users.',0,6,0,'$js_default_url_local = $modx->config[\'site_url\']. \'/assets/js/jquery.min.js\';\n$js_default_url_remote = \'http://ajax.googleapis.com/ajax/libs/jquery/1.8/jquery.min.js\';\n$asset_path = $modx->config[\'base_path\'] . \'assets/plugins/managermanager/mm.inc.php\';\ninclude($asset_path);\n',0,'&config_chunk=Configuration Chunk;text;mm_rules; &remove_deprecated_tv_types_pref=Remove deprecated TV types;list;yes,no;yes &which_jquery=jQuery source;list;local (assets/js),remote (google code),manual url (specify below);local (assets/js) &js_src_type=jQuery URL override;text;',1,'',0,0),(5,'Quick Manager+','<strong>1.5.6</strong> Enables QuickManager+ front end content editing support',0,6,0,'// In manager\nif (isset($_SESSION[\'mgrValidated\'])) {\n\n    $show = TRUE;\n\n    if ($disabled  != \'\') {\n        $arr = explode(\",\", $disabled );\n        if (in_array($modx->documentIdentifier, $arr)) {\n            $show = FALSE;\n        }\n    }\n\n    if ($show) {\n        // Replace [*#tv*] with QM+ edit TV button placeholders\n        if ($tvbuttons == \'true\') {\n            $e = $modx->Event;\n            if ($e->name == \'OnParseDocument\') {\n                 $output = &$modx->documentOutput;\n                 $output = preg_replace(\'~\\[\\*#(.*?)\\*\\]~\', \'<!-- \'.$tvbclass.\' $1 -->[*$1*]\', $output);\n                 $modx->documentOutput = $output;\n             }\n         }\n        // In manager\n        if (isset($_SESSION[\'mgrValidated\'])) {\n            include_once($modx->config[\'base_path\'].\'assets/plugins/qm/qm.inc.php\');\n            $qm = new Qm($modx, $jqpath, $loadmanagerjq, $loadfrontendjq, $noconflictjq, $loadtb, $tbwidth, $tbheight, $hidefields, $hidetabs, $hidesections, $addbutton, $tpltype, $tplid, $custombutton, $managerbutton, $logout, $autohide, $editbuttons, $editbclass, $newbuttons, $newbclass, $tvbuttons, $tvbclass);\n        }\n    }\n}\n',0,'&jqpath=Path to jQuery;text;assets/js/jquery.min.js &loadmanagerjq=Load jQuery in manager;list;true,false;false &loadfrontendjq=Load jQuery in front-end;list;true,false;true &noconflictjq=jQuery noConflict mode in front-end;list;true,false;true &loadtb=Load modal box in front-end;list;true,false;true &tbwidth=Modal box window width;text;80% &tbheight=Modal box window height;text;90% &hidefields=Hide document fields from front-end editors;text;parent &hidetabs=Hide document tabs from front-end editors;text; &hidesections=Hide document sections from front-end editors;text; &addbutton=Show add document here button;list;true,false;true &tpltype=New document template type;list;parent,id,selected;parent &tplid=New document template id;int;3 &custombutton=Custom buttons;textarea; &1=undefined;; &managerbutton=Show go to manager button;list;true,false;true &logout=Logout to;list;manager,front-end;manager &disabled=Plugin disabled on documents;text; &autohide=Autohide toolbar;list;true,false;true &editbuttons=Inline edit buttons;list;true,false;false &editbclass=Edit button CSS class;text;qm-edit &newbuttons=Inline new resource buttons;list;true,false;false &newbclass=New resource button CSS class;text;qm-new &tvbuttons=Inline template variable buttons;list;true,false;false &tvbclass=Template variable button CSS class;text;qm-tv',1,'',0,0),(6,'TinyMCE Rich Text Editor','<strong>3.5.10</strong> Javascript WYSIWYG Editor',0,6,0,'require MODX_BASE_PATH.\'assets/plugins/tinymce/plugin.tinymce.php\';',0,'&customparams=Custom Parameters;textarea;valid_elements : \"*[*]\", &mce_formats=Block Formats;text;p,h1,h2,h3,h4,h5,h6,div,blockquote,code,pre &entity_encoding=Entity Encoding;list;named,numeric,raw;named &entities=Entities;text; &mce_path_options=Path Options;list;Site config,Absolute path,Root relative,URL,No convert;Site config &mce_resizing=Advanced Resizing;list;true,false;true &disabledButtons=Disabled Buttons;text; &link_list=Link List;list;enabled,disabled;enabled &webtheme=Web Theme;list;simple,editor,creative,custom;simple &webPlugins=Web Plugins;text;style,advimage,advlink,searchreplace,contextmenu,paste,fullscreen,xhtmlxtras,media &webButtons1=Web Buttons 1;text;undo,redo,selectall,|,pastetext,pasteword,|,search,replace,|,hr,charmap,|,image,link,unlink,anchor,media,|,cleanup,removeformat,|,fullscreen,code,help &webButtons2=Web Buttons 2;text;bold,italic,underline,strikethrough,sub,sup,|,|,blockquote,bullist,numlist,outdent,indent,|,justifyleft,justifycenter,justifyright,justifyfull,|,styleselect,formatselect,|,styleprops &webButtons3=Web Buttons 3;text; &webButtons4=Web Buttons 4;text; &webAlign=Web Toolbar Alignment;list;ltr,rtl;ltr &width=Width;text;95% &height=Height;text;500',1,'',0,0),(7,'TransAlias','<strong>1.0.2</strong> Human readible URL translation supporting multiple languages and overrides',0,6,0,'require MODX_BASE_PATH.\'assets/plugins/transalias/plugin.transalias.php\';',0,'&table_name=Trans table;list;common,russian,utf8,utf8lowercase;russian &char_restrict=Restrict alias to;list;lowercase alphanumeric,alphanumeric,legal characters;lowercase alphanumeric &remove_periods=Remove Periods;list;Yes,No;No &word_separator=Word Separator;list;dash,underscore,none;dash &override_tv=Override TV name;string;',1,'',0,0),(9,'CacheAccelerator','<strong>0.4b</strong> Clear CacheAccelerator cache files and managing autocache',0,0,0,'if(!function_exists(\'processInjection\')){\n    function processInjection($str, $autoCacheSnippets, $autoCacheExcludeSnippets, $dropCacheFields, $showSnippets){\n        $pos = 0;\n        while($pos = strpos($str, \'[!\', $pos)){\n            if($pos1 = strpos($str, \'!]\', $pos)){\n                $pos3 = $pos1;\n                $pos2 = strpos($str, \'?\', $pos);\n                if($pos2 && $pos1 > $pos2){\n                    $pos1 = $pos2;\n                    $offs = 1;\n                } else\n                    $offs = 0;\n                $pos+=2;\n                $snippetToCache = trim(substr($str, $pos, $pos1 - $pos));\n                $symb = strtolower($snippetToCache[0]);\n                if($symb >= \'a\' && $symb <= \'z\' && strtolower($snippetToCache) != \'cacheaccelerator\'){\n                    if(!is_null($autoCacheSnippets)){\n                        if(!in_array($snippetToCache, $autoCacheSnippets)){\n                            continue;\n                        }\n                    }\n                    if(!is_null($autoCacheExcludeSnippets)){\n                        if(in_array($snippetToCache, $autoCacheExcludeSnippets)){\n                            continue;\n                        }\n                    }\n                    $dcfStr = ($dropCacheFields != \'\') ? \' &dropCacheField=`\'.str_replace(\',\', \';\', $dropCacheFields).\'`\' : \'\';\n                    $logMessages = ($showSnippets != \'no\') ? \' &logMessages=`1`\' : \'\';\n                    if($showSnippets == \'short\')\n                        echo(\'CacheAccelerator Caching: \'.$snippetToCache.\'<br />\');\n                    if($showSnippets == \'full\')\n                        echo(\'CacheAccelerator Caching: \'.$snippetToCache.\', Call: [!CacheAccelerator? &snippetToCache=`\'.$snippetToCache.\'`\'.$logMessages.\' &cacheId=`\'.md5(substr($str, $pos, $pos3 - $pos)).\'`\'.$dcfStr.substr($str, $pos1, $pos3 - $pos1).\'!]<br /><br />\');\n\n                    $str = substr($str, 0, $pos).\'CacheAccelerator? &snippetToCache=`\'.$snippetToCache.\'`\'.$logMessages.\' &cacheId=`\'.md5(substr($str, $pos, $pos3 - $pos)).\'`\'.$dcfStr.substr($str, $pos1 + $offs);\n                }\n            }\n        }\n        return $str;\n    }\n}\n\n$only_manual = isset($only_manual) ? $only_manual : \'no\';\n$e = &$modx->Event;\n\nif($e->name == \'OnWebPagePrerender\'){\n    if($showSystemData == \'yes\'){\n//        if($modx->checkSession()){\n\n            $out = \"<div style=\'clear:both\'>&nbsp;</div>MySQL: [^qt^], [^q^] request(s), PHP: [^p^], total: [^t^], Memory: [^m^], document retrieved from [^s^]. \";\n            $totalTime= ($modx->getMicroTime() - $modx->tstart);\n            $queryTime= $modx->queryTime;\n            $phpTime= $totalTime - $queryTime;\n\n            $queryTime= sprintf(\"%2.4f s\", $queryTime);\n            $totalTime= sprintf(\"%2.4f s\", $totalTime);\n            $phpTime= sprintf(\"%2.4f s\", $phpTime);\n            $phpMemory = (memory_get_peak_usage(true) / 1024 / 1024) . \" MB\";\n            $source= $modx->documentGenerated == 1 ? \"database\" : \"cache\";\n            $queries= isset ($modx->executedQueries) ? $modx->executedQueries : 0;\n            $out= str_replace(\"[^m^]\", $phpMemory, $out);\n            $out= str_replace(\"[^q^]\", $queries, $out);\n            $out= str_replace(\"[^qt^]\", $queryTime, $out);\n            $out= str_replace(\"[^p^]\", $phpTime, $out);\n            $out= str_replace(\"[^t^]\", $totalTime, $out);\n            $out= str_replace(\"[^s^]\", $source, $out);\n            $this->documentOutput .= $out;\n//        }\n    }\n    return;\n}\n\nif($autoCache == \'enabled\' && $e->name == \'OnLoadWebDocument\'){\n    if($autoCacheSnippets != \'\' && $autoCacheSnippets != \'all\'){\n        $autoCacheSnippets = trim(preg_replace(\'|\\\\s*(?:\'.preg_quote(\',\').\')\\\\s*|\', \',\', $autoCacheSnippets));\n        $autoCacheSnippets = explode(\",\", $autoCacheSnippets);\n    } else\n        $autoCacheSnippets = null;\n    if($autoCacheExcludeSnippets != \'\'){\n        $autoCacheExcludeSnippets = trim(preg_replace(\'|\\\\s*(?:\'.preg_quote(\',\').\')\\\\s*|\', \',\', $autoCacheExcludeSnippets));\n        $autoCacheExcludeSnippets = explode(\",\", $autoCacheExcludeSnippets);\n    } else\n        $autoCacheExcludeSnippets = null;\n    foreach($modx->chunkCache as $key => $chunk)\n        $modx->chunkCache[$key] = processInjection($chunk, $autoCacheSnippets, $autoCacheExcludeSnippets, $dropCacheFields, $showSnippets);\n    $modx->documentContent = processInjection($modx->documentContent, $autoCacheSnippets, $autoCacheExcludeSnippets, $dropCacheFields, $showSnippets);\n    $modx->documentObject[\'content\'] = processInjection($modx->documentObject[\'content\'], $autoCacheSnippets, $autoCacheExcludeSnippets, $dropCacheFields, $showSnippets);\n    return;\n}\n\nif (($e->name == \'OnCacheUpdate\' && $only_manual==\'no\') || ($e->name == \'OnSiteRefresh\' && $only_manual==\'yes\')) {\n    $path_to_cacheengine = $modx->config[\'base_path\'].\"assets/plugins/cacheaccelerator/\";\n    $path_to_cache = $modx->config[\'base_path\'].\"assets/plugins/cacheaccelerator/cache/\";\n    require_once $path_to_cacheengine.\"fileCache.php\";\n    $cache = fileCache::GetInstance(84600*7,$path_to_cache);\n    if($dropCacheGroups != \'\' && $dropCacheGroups != \'all\'){\n        $dropCacheGroups = trim(preg_replace(\'|\\\\s*(?:\'.preg_quote(\',\').\')\\\\s*|\', \',\', $dropCacheGroups));\n        $dropCacheGroups = explode(\",\", $dropCacheGroups);\n        $cache->deleteCache(0, $dropCacheGroups);\n    } else\n        $cache->deleteCache(0);\n    return;\n}\n\n',0,'&only_manual=Only manual clear;list;yes,no;no &autoCache=Autocache;list;enabled,disabled;disabled &autoCacheSnippets=Snippets to Autocache (\'ditto,jot\');string;all &autoCacheExcludeSnippets=Snippets to exclude (\'snippet1, snippet2\');string;include &dropCacheGroups=Groups to clear (\'default, news\');string;all &dropCacheFields=Drop cache fields;string;JotForm||post,true,2||,publish,2||,unpublish,2||,delete,2||,edit,2 &showSnippets=Show snippets log;list;full,short,no;no &showSystemData=Show system data;list;yes,no;no',0,' ',0,0),(17,'YandexMetrika','<strong>0.1</strong> YandexMetrika',0,9,0,'//Во вкладке Сайт меняем значение radiobutton Регистрировать посещения на Да\n// Is stats tracking turned on in the Site Config?\nif ($modx->getConfig(\'track_visitors\') != 1) {\n    return; \n}\n\n\n// Read Config Parameters\n$account = isset($account) && $account != \'000000\' ? $account : \'\'; // Ignore default value\n$testMode = isset($testMode) && ($testMode == \'true\') ? true: false;\n$clickmap = isset($clickmap) && ($clickmap == \'true\') ? true: false;\n$tracklinks = isset($tracklinks) && ($tracklinks == \'true\') ? true: false;\n$async = isset($async) && ($async == \'true\') ? true: false;\n\n\n// make sure an account number has been supplied\nif(!empty($account)) {\n\n    // Options\n    if($clickmap) {\n        $clickmapString = \"\n            yaCounter$account.clickmap(true);\";\n    }\n\n    if($tracklinks) {\n        $tracklinksString = \"\n            yaCounter$account.trackLinks(true);\";\n    }\n\n    $options = \"$clickmapString$tracklinksString\";\n\n    if($async) {\n\n        $script = \"\n<div style=\\\"display:none;\\\"><script type=\\\"text/javascript\\\">\n(function(w, c) {\n    (w[c] = w[c] || []).push(function() {\n        try {\n            w.yaCounter$account = new Ya.Metrika($account);$options\n        } catch(e) { }\n    });\n})(window, \'yandex_metrika_callbacks\');\n</script></div>\n<script src=\\\"//mc.yandex.ru/metrika/watch.js\\\" type=\\\"text/javascript\\\" defer=\\\"defer\\\"></script>\n<noscript><div><img src=\\\"//mc.yandex.ru/watch/$account\\\" style=\\\"position:absolute; left:-9999px;\\\" alt=\\\"\\\" /></div></noscript>\";\n\n    } else {\n\n        $script = \"\n<script src=\\\"//mc.yandex.ru/metrika/watch.js\\\" type=\\\"text/javascript\\\"></script>\n<div style=\\\"display:none;\\\"><script type=\\\"text/javascript\\\">\ntry { var yaCounter$account = new Ya.Metrika($account);$options} catch(e) { }\n</script></div>\n<noscript><div><img src=\\\"//mc.yandex.ru/watch/$account\\\" style=\\\"position:absolute; left:-9999px;\\\" alt=\\\"\\\" /></div></noscript>\";\n    \n    }\n\n    $insert_before = \'body\';\n\n} else {\n\n    $script = \'<!-- Yandex.Metrika account not supplied -->\'; \n\n}\n\n\nswitch ($modx->Event->name) { \n    \n    case \"OnWebPagePrerender\":\n\n        if ($testMode) {\n            $script = \'<!-- Yandex.Metrika plugin is in test mode - output would be: \'. $script . \' -->\'; \n        } else if (isset($_SESSION[\'mgrValidated\'])) {\n            $script = \'<!-- Logged in to Manager - Yandex.Metrika plugin output surpressed, but would be: \'. $script . \' -->\';    \n        }\n                \n        // Only track HTML documents, in the front end, which have the \"Track\" box checked in the Manager\n        $yandexize = ($modx->isFrontEnd() && $modx->documentObject[\'donthit\']==0 && $modx->documentObject[\'contentType\']==\'text/html\');\n        \n        if ($yandexize) {\n            $modx->documentOutput = preg_replace(\"/(<\\/$insert_before>)/i\", $script.\"\\n\\\\1\", $modx->documentOutput);            \n        }\n        \n        break;\n\n}',0,'&account=Account ID;string;000000 &testMode=Тестовый режим;list;true,false;false &clickmap=Карта кликов;list;true,false;true &tracklinks=Внешние ссылки;list;true,false;true &async=Асинхронный код;list;true,false;true',0,'',0,0),(15,'MinifyX','<strong>1.0</strong> Minify CSS and JS',0,0,0,'if($modx->Event->name==\'OnDocFormSave\'){\n\n  //$modx->db->update(array(\'content\'=>$data),$modx->getFullTableName(\"site_content\"),\"id=\'58\'\");\n  	$param=$modx->event->params;\n	  $param[\'API\']=\'1\';\n\n  $mode=false;\n  	if($param[\'id\']==$param[\'CSSdoc\'] && (int)$param[\'CSSdoc\']>0){\n  		$param[\'JSdoc\']=\'\';\n      $param[\'JSfile\']=\'\';\n      $mode=\'css\';\n  	}else{\n    	if($param[\'id\']==$param[\'JSdoc\'] && (int)$param[\'JSdoc\']>0){\n  			$param[\'CSSdoc\']=\'\';\n      	$param[\'CSSfile\']=\'\';\n        $mode=\'js\';\n  		} \n    }\n  switch($mode){\n    case \'css\':\n    case \'js\':{\n  		$flag=$modx->runSnippet(\"MinifyX\",$param);\n      break;\n    }\n    default:{\n    	break;\n    }\n  }\n}',0,'',0,' ',0,0),(19,'PHx','<strong>2.2.0</strong> (Placeholders Xtended) Adds the capability of output modifiers when using placeholders, template variables and settings tags',0,6,0,'if (!class_exists(\'PHxParser\')) {\n    include MODX_BASE_PATH . \"assets/plugins/phx/phx.parser.class.inc.php\";\n}\n\n$e = &$modx->Event;\nswitch($e->name) {\n	case \'OnParseDocument\':\n		$PHx = new PHxParser($phxdebug,$phxmaxpass);\n		$PHx->OnParseDocument();\n		break;\n}\n',0,'&phxdebug=Log events;int;0 &phxmaxpass=Max. Passes;int;50',0,'',0,0),(21,'VirtualAliases','<strong>0.0.3</strong> Allows for an unlimited number of custom aliases per page.',0,11,0,'$e = &$modx->event;\n\nif ($e->name == \"OnPageNotFound\") {\n   // Retrieve requested path + alias\n   $documentAlias = str_replace($modx->config[\'friendly_url_suffix\'], \'\', $_REQUEST[\'q\']);\n\n   // Search TVs for potential alias matches\n   $sql = \"SELECT tvc.contentid as id, tvc.value as value FROM \" . $modx->getFullTableName(\'site_tmplvars\') . \" tv \";\n   $sql .= \"INNER JOIN \" . $modx->getFullTableName(\'site_tmplvar_templates\') . \" tvtpl ON tvtpl.tmplvarid = tv.id \";\n   $sql .= \"LEFT JOIN \" . $modx->getFullTableName(\'site_tmplvar_contentvalues\') . \" tvc ON tvc.tmplvarid = tv.id \";\n   $sql .= \"LEFT JOIN \" . $modx->getFullTableName(\'site_content\') . \" sc ON sc.id = tvc.contentid \";\n   $sql .= \"WHERE sc.published = 1 AND tvtpl.templateid = sc.template AND tv.name = \'$aliasesTV\' AND tvc.value LIKE \'%\" . $modx->db->escape($documentAlias) . \"%\'\";\n   $results = $modx->dbQuery($sql);\n\n   // Attempt to find an exact match\n   $found = 0;\n   while ($found == 0 && $row = $modx->db->getRow($results)) {\n      $pageAliases = explode(\"\\n\", $row[\"value\"]);\n      while ($found == 0 && $alias = each($pageAliases)) {\n         if (trim($alias[1]) == $documentAlias) {\n            // Check for a match\n            $found = $row[\"id\"];\n         }\n      }\n   }\n\n   if ($found) {\n      // Redirect to new document, if an alias was found\n      if ($found == $modx->config[\'site_start\']) {\n         $pageUrl = $modx->config[\'site_url\'];\n      } else {\n         $pageUrl = $modx->makeUrl($found, \'\', \'\', \"full\");\n      }\n\n      // Send a permanent redirect\n      $modx->sendRedirect($pageUrl, 0, \"REDIRECT_HEADER\", \"HTTP/1.1 301 Moved Permanently\");\n      exit(0);\n   }\n\n   header(\"HTTP/1.0 404 Not Found\");\n   header(\"Status: 404 Not Found\");\n}',0,'&aliasesTV=Aliases TV name;string;Aliases',0,'',0,0),(23,'Strict URLs','',0,0,0,'//<?php\n// Strict URLs\n// version 1.0.1\n// Enforces the use of strict URLs to prevent duplicate content.\n// By Jeremy Luebke @ www.xuru.com\n// Contributions by Brian Stanback @ www.stanback.net\n\n// On Install: Check the \"OnWebPageInit\" & \"OnWebPagePrerender\" boxes in the System Events tab.\n// Plugin configuration: &editDocLinks=Edit document links;int;1 &makeFolders=Rewrite containers as folders;int;1 &emptyFolders=Check for empty container when rewriting;int;0 &override=Enable manual overrides;int;0 &overrideTV=Override TV name;string;seoOverride\n\n// For overriding documents, create a new template variabe (TV) named seoOverride with the following options:\n//    Input Type: DropDown List Menu\n//    Input Option Values: Disabled==-1||Base Name==0||Append Extension==1||Folder==2\n//    Default Value: -1\n\n//  # Include the following in your .htaccess file\n//  # Replace \"example.com\" &  \"example\\.com\" with your domain info\n//  RewriteCond %{HTTP_HOST} .\n//  RewriteCond %{HTTP_HOST} !^www\\.example\\.com [NC]\n//  RewriteRule (.*) http://www.example.com/$1 [R=301,L] \n\n// Begin plugin code\n$e = &$modx->event;\n\nif ($e->name == \'OnWebPageInit\') \n{\n   $documentIdentifier = $modx->documentIdentifier;\n\n   if ($documentIdentifier)  // Check for 404 error\n   {\n      $myProtocol = ($_SERVER[\'HTTPS\'] == \'on\') ? \'https\' : \'http\';\n      $s = $_SERVER[\'REQUEST_URI\'];\n      $parts = explode(\"?\", $s);  \n\n      $alias = $modx->aliasListing[$documentIdentifier][\'alias\'];\n      if ($makeFolders)\n      {\n         if ($emptyFolders)\n         {\n            $result = $modx->db->select(\'isfolder\', $modx->getFullTableName(\'site_content\'), \'id = \' . $documentIdentifier);\n            $isfolder = $modx->db->getValue($result);\n         }\n         else\n         {\n            $isfolder = (count($modx->getChildIds($documentIdentifier, 1)) > 0) ? 1 : 0;\n         }\n      }\n\n      if ($override && $overrideOption = $modx->getTemplateVarOutput($overrideTV, $documentIdentifier))\n      {\n         switch ($overrideOption[$overrideTV])\n         {\n            case 0:\n               $isoverride = 1;\n               break;\n            case 1:\n               $isfolder = 0;\n               break;\n            case 2:\n               $makeFolders = 1;\n               $isfolder = 1;\n         }\n      }\n\n      if ($isoverride)\n      {\n         $strictURL = preg_replace(\'/[^\\/]+$/\', $alias, $modx->makeUrl($documentIdentifier));\n      }\n      elseif ($isfolder && $makeFolders)\n      {\n         $strictURL = preg_replace(\'/[^\\/]+$/\', $alias, $modx->makeUrl($documentIdentifier)) . \"/\";\n      }\n      else\n      {\n         $strictURL = $modx->makeUrl($documentIdentifier);\n      }\n\n      $myDomain = $myProtocol . \"://\" . $_SERVER[\'HTTP_HOST\'];\n      $newURL = $myDomain . $strictURL;\n      $requestedURL = $myDomain . $parts[0];\n\n      if ($documentIdentifier == $modx->config[\'site_start\'])\n      {\n         if ($requestedURL != $modx->config[\'site_url\'])\n         {\n            // Force redirect of site start\n            header(\"HTTP/1.1 301 Moved Permanently\");\n            $qstring = preg_replace(\"#(^|&)(q|id)=[^&]+#\", \'\', $parts[1]);  // Strip conflicting id/q from query string\n            if ($qstring) header(\'Location: \' . $modx->config[\'site_url\'] . \'?\' . $qstring);\n            else header(\'Location: \' . $modx->config[\'site_url\']);\n            exit(0);\n         }\n      }\n      elseif ($parts[0] != $strictURL)\n      {\n         // Force page redirect\n         header(\"HTTP/1.1 301 Moved Permanently\");\n         $qstring = preg_replace(\"#(^|&)(q|id)=[^&]+#\", \'\', $parts[1]);  // Strip conflicting id/q from query string\n         if ($qstring) header(\'Location: \' . $strictURL . \'?\' . $qstring);\n         else header(\'Location: \' . $strictURL);\n         exit(0);\n      }\n   }\n}\nelseif ($e->name == \'OnWebPagePrerender\')\n{\n   if ($editDocLinks)\n   {\n      $myDomain = $_SERVER[\'HTTP_HOST\'];\n      $furlSuffix = $modx->config[\'friendly_url_suffix\'];\n      $baseUrl = $modx->config[\'base_url\'];\n      $o = &$modx->documentOutput; // get a reference of the output\n\n      // Reduce site start to base url\n      $overrideAlias = $modx->aliasListing[$modx->config[\'site_start\']][\'alias\'];\n      $overridePath = $modx->aliasListing[$modx->config[\'site_start\']][\'path\'];\n      $o = preg_replace(\"#((href|action)=\\\"|$myDomain)($baseUrl)?($overridePath/)?$overrideAlias$furlSuffix#\", \'${1}\' . $baseUrl, $o);\n\n      if ($override)\n      {\n         // Replace manual override links\n         $sql = \"SELECT tvc.contentid as id, tvc.value as value FROM \" . $modx->getFullTableName(\'site_tmplvars\') . \" tv \";\n         $sql .= \"INNER JOIN \" . $modx->getFullTableName(\'site_tmplvar_templates\') . \" tvtpl ON tvtpl.tmplvarid = tv.id \";\n         $sql .= \"LEFT JOIN \" . $modx->getFullTableName(\'site_tmplvar_contentvalues\') . \" tvc ON tvc.tmplvarid = tv.id \";\n         $sql .= \"LEFT JOIN \" . $modx->getFullTableName(\'site_content\') . \" sc ON sc.id = tvc.contentid \";\n         $sql .= \"WHERE sc.published = 1 AND tvtpl.templateid = sc.template AND tv.name = \'$overrideTV\'\";\n         $results = $modx->dbQuery($sql);\n         while ($row = $modx->fetchRow($results))\n         {\n            $overrideAlias = $modx->aliasListing[$row[\'id\']][\'alias\'];\n            $overridePath = $modx->aliasListing[$row[\'id\']][\'path\'];\n            switch ($row[\'value\'])\n            {\n               case 0:\n                  $o = preg_replace(\"#((href|action)=\\\"($baseUrl)?($overridePath/)?|$myDomain$baseUrl$overridePath/?)$overrideAlias$furlSuffix#\", \'${1}\' . $overrideAlias, $o);\n                  break;\n               case 2:\n                  $o = preg_replace(\"#((href|action)=\\\"($baseUrl)?($overridePath/)?|$myDomain$baseUrl$overridePath/?)$overrideAlias$furlSuffix/?#\", \'${1}\' . rtrim($overrideAlias, \'/\') . \'/\', $o);\n                  break;\n            }\n         }\n      }\n\n      if ($makeFolders)\n      {\n         if ($emptyFolders)\n         {\n            // Populate isfolder array\n            $isfolder_arr = array();\n            $result = $modx->db->select(\'id\', $modx->getFullTableName(\'site_content\'), \'published > 0 AND isfolder > 0\');\n            while ($row = $modx->db->getRow($result))\n               $isfolder_arr[$row[\'id\']] = true;\n         }\n\n         // Replace container links\n         foreach ($modx->documentListing as $id)\n         {\n            if ((is_array($isfolder_arr) && isset($isfolder_arr[$id])) || count($modx->getChildIds($id, 1)))\n            {\n               $overrideAlias = $modx->aliasListing[$id][\'alias\'];\n               $overridePath = $modx->aliasListing[$id][\'path\'];\n               $o = preg_replace(\"#((href|action)=\\\"($baseUrl)?($overridePath/)?|$myDomain$baseUrl$overridePath/?)$overrideAlias$furlSuffix/?#\", \'${1}\' . rtrim($overrideAlias, \'/\') . \'/\', $o);\n            }\n         }\n      }\n   }\n}\n',0,'&editDocLinks=Edit document links;int;1 &makeFolders=Rewrite containers as folders;int;0 &emptyFolders=Check for empty container when rewriting;int;0 &override=Enable manual overrides;int;0 &overrideTV=Override TV name;string;seoOverride',0,' ',0,0),(25,'RedirectMap','',0,0,0,'     global $modx;\n    $mapChunk = $modx->getChunk($chunk);\n    $mapLines = explode(\"\\n\",$mapChunk);\n    $mapArr = array();\n    foreach($mapLines as $line) {\n    list($link,$redirectId) = explode(\'||\',$line);\n    $mapArr[$link] = $redirectId;\n    }\n    $q = $_REQUEST[\'q\'];\n    if(isset($mapArr[$q])) {\n    $url = $modx->makeUrl($mapArr[$q]);\n    $modx->sendRedirect($url,0,\'REDIRECT_HEADER\',\'HTTP/1.1 301 Moved Permanently\');\n    exit();\n    }',0,'&chunk=Чанк с картой редиректов;text;КартаРедиректов',0,' ',0,0),(26,'Forgot Manager Login','<strong>1.1.7</strong> Resets your manager login when you forget your password via email confirmation',0,6,0,'require MODX_BASE_PATH.\'assets/plugins/forgotmanagerlogin/plugin.forgotmanagerlogin.php\';',0,'',0,'',0,0),(27,'OutdatedExtrasCheck','<strong>1.4.6</strong> Check for Outdated critical extras not compatible with EVO 1.4.6',0,6,0,'/**\n * OutdatedExtrasCheck\n *\n * Check for Outdated critical extras not compatible with EVO 1.4.6\n *\n * @category	plugin\n * @version     1.4.6\n * @license 	http://www.gnu.org/copyleft/gpl.html GNU Public License (GPL)\n * @package     evo\n * @author      Author: Nicola Lambathakis\n * @internal    @events OnManagerWelcomeHome\n * @internal    @properties &wdgVisibility=Show widget for:;menu;All,AdminOnly,AdminExcluded,ThisRoleOnly,ThisUserOnly;AdminOnly &ThisRole=Run only for this role:;string;;;(role id) &ThisUser=Run only for this user:;string;;;(username)\n * @internal    @modx_category Manager and Admin\n * @internal    @installset base\n * @internal    @disabled 0\n */\n\nrequire MODX_BASE_PATH . \'assets/plugins/extrascheck/OutdatedExtrasCheck.plugin.php\';\n',0,'{\"wdgVisibility\":[{\"label\":\"Show widget for:\",\"type\":\"menu\",\"value\":\"AdminOnly\",\"options\":\"All,AdminOnly,AdminExcluded,ThisRoleOnly,ThisUserOnly\",\"default\":\"AdminOnly\",\"desc\":\"\"}],\"ThisRole\":[{\"label\":\"Run only for this role:\",\"type\":\"string\",\"value\":\"\",\"default\":\"\",\"desc\":\"\"}],\"ThisUser\":[{\"label\":\"Run only for this user:\",\"type\":\"string\",\"value\":\"\",\"default\":\"\",\"desc\":\"\"}]}',0,'',0,0),(28,'Updater','<strong>0.8.4</strong> show message about outdated CMS version',0,6,0,'require MODX_BASE_PATH.\'assets/plugins/updater/plugin.updater.php\';\n\n\n',0,'{\"version\":[{\"label\":\"Version:\",\"type\":\"text\",\"value\":\"evolution-cms\\/evolution\",\"default\":\"evolution-cms\\/evolution\",\"desc\":\"\"}],\"wdgVisibility\":[{\"label\":\"Show widget for:\",\"type\":\"menu\",\"value\":\"All\",\"options\":\"All,AdminOnly,AdminExcluded,ThisRoleOnly,ThisUserOnly\",\"default\":\"All\",\"desc\":\"\"}],\"ThisRole\":[{\"label\":\"Show only to this role id:\",\"type\":\"string\",\"value\":\"\",\"default\":\"\",\"desc\":\"\"}],\"ThisUser\":[{\"label\":\"Show only to this username:\",\"type\":\"string\"