INSERT INTO `modx_site_templates` VALUES (3,'Home',NULL,'',0,0,'',0,'{{header}}\n<body>\n	<div class=\"vcard\">\n<div id=\"main\">\n	<div id=\"main_center\">\n		<div id=\"header\">\n			<div class=\"linkblock\" onclick=\"location.href=\'/\';\">\n				<div class=\"logo\">	\n				</div>\n			</div>\n			{{contact}}\n		</div>\n		\n			{{menu}}\n\n	<div id=\"news_and_articles\">\n			\n			</div>\n\n			<div id=\"bottle_price\">\n						<div id=\"bottle1\">\n					<div class=\"cont_t\"><!--Blue Rain !-->помпа для воды</div>\n				<img alt=\"помпа для воды\" src=\"[*img*]\" width=\"145\" height=\"275\">\n<ul>\n<li class=\"price\">[*index_title*]</li>\n<li>[*index_mtitle*]</li>\n</ul>\n<a href= \"[~6~]#part2\" class=\"readmorebottle\">подробнее</a>	<!-- target=\"_blank\" для открытие в новой вкладке всавить после класса!-->\n							</div>\n				\n										<div id=\"bottle2\">\n													<div class=\"cont_t\"> [*index_title2*]</div>\n											<img itemprop=\"logo\" alt=\"бутыль с водой\" src=\"[*img2*]\" width=\"150\" height=\"276\"><br>\n<ul>\n<li class=\"price\">[*price*]</li>\n<li>[*index_mtitle2*]</li>\n<li>[*2index_mtitle2*]</li>\n<li>[*3index_mtitle2*]</li>\n</ul>\n<a href=\"[~6~]#part1\" class=\"readmorebottle\">подробнее</a>	\n							</div>\n													<div id=\"bottle3\">\n													<div class=\"cont_t\">Кулер</div>\n														<img alt=\"kyler\" src=\"[*img3*]\" width=\"145\" height=\"275\"><br>\n<ul>\n<li class=\"price\">[*index_title3*]</li>\n<li>[*3index_mtitle3*]</li>\n</ul>\n<a href=\"[~6~]#part3\" class=\"readmorebottle\">подробнее</a>	\n							</div>\n					</div>\n	\n		<div id=\"conteiner_content\">\n			\n			<div id=\"content\">\n										\n				<div class=\"main_content\">\n					\n<div id=\"system-message-container\">\n</div>\n					<div class=\"item-page\" itemprop=\"address\">\n\n	<h1> Доставка воды Бровары </h1>\n \n\n\n\n\n\n\n<div class=\"content-links\">\n	<ul>\n			</ul>\n	</div>\n\n[*content*] \n\n	\n	\n</div>\n\n				</div>\n				\n						\n								\n			</div>\n			{{right_block}}\n		\n		</div>\n	</div>\n				<script type=\"text/javascript\">\n$(document).ready(function(){\n \n$(window).scroll(function(){\nif ($(this).scrollTop() > 100) {\n$(\'.scrollup\').fadeIn();\n} else {\n$(\'.scrollup\').fadeOut();\n}\n});\n \n$(\'.scrollup\').click(function(){\n$(\"html, body\").animate({ scrollTop: 0 }, 600);\nreturn false;\n});\n \n});\n			</script>\n<div id=\"clear_line\"></div>	\n		{{footer}}\n		</div>\n\n	</div></body></html>',0,1,0,0),(13,'Duplicate of Home',NULL,'',0,0,'',0,'{{header}}\n<body>\n<div id=\"main\">\n	<div id=\"main_center\">\n		<div id=\"header\">\n			<div class=\"logo\">\n				<a id=\"logo\" href=\"[(site_url)]\"></a>\n			</div>\n							{{contact}}\n					</div>\n	\n	<div id=\"clear_line\"></div>\n								{{menu}}\n			\n	<div id=\"clear_line\"></div>\n	<div id=\"news_and_articles\">\n			\n			</div>\n	<div id=\"clear_line\"></div>\n			<div id=\"bottle_price\">\n										<div id=\"bottle1\">\n													<h3>Blue Rain помпа для воды</h3>\n				<img alt=\"помпа для воды\" src=\"[*img*]\" width=\"137\" height=\"275\">\n<ul>\n<li class=\"price\">[*index_title*]</li>\n<li>[*index_mtitle*]</li>\n</ul>\n<a href=\"[~6~]\" class=\"readmorebottle\">подробнее</a>	\n							</div>\n				\n										<div id=\"bottle2\">\n													<h3> [*index_title2*]</h3>\n											<img alt=\"бутыль с водой\" src=\"[*img2*]\" width=\"165\" height=\"276\"><br>\n<ul>\n<li class=\"price\">[*price*]</li>\n<li>[*index_mtitle2*]</li>\n<li>[*2index_mtitle2*]</li>\n<li>[*3index_mtitle2*]</li>\n</ul>\n<a href=\"[~6~]\" class=\"readmorebottle\">подробнее</a>	\n							</div>\n													<div id=\"bottle3\">\n													<h3>Кулер</h3>\n														<img alt=\"kyler\" src=\"[*img3*]\" width=\"152\" height=\"281\"><br>\n<ul>\n<li class=\"price\">[*index_title3*]</li>\n<li>[*3index_mtitle3*]</li>\n</ul>\n<a href=\"[~6~]\" class=\"readmorebottle\">подробнее</a>	\n							</div>\n					</div>\n		<div id=\"clear_line\"></div>\n		<div id=\"conteiner_content\">\n			\n			<div id=\"content\">\n												<div id=\"clear_line\"></div>		\n				<div class=\"main_content\">\n					\n<div id=\"system-message-container\">\n</div>\n					<div class=\"item-page\">\n\n	<h1> Доставка воды Бровары \"Кришталево-чиста питна вода\"</h1> ™		\n\n\n\n\n\n\n\n<div class=\"content-links\">\n	<ul>\n			</ul>\n	</div>\n\n<p>[*content*]</p> \n	\n</div>\n\n				</div>\n				<div id=\"clear_line\"></div>		\n								<div id=\"clear_line\"></div>		\n								<div id=\"clear_line\"></div>		\n								\n			</div>\n			{{right_block}}\n			<div id=\"clear_line\"></div>\n		</div>\n	</div>\n<div id=\"clear_line\"></div>	\n		{{footer}}\n		</div>\n</div>	\n<script type=\"text/javascript\">\n\n  var _gaq = _gaq || [];\n  _gaq.push([\'_setAccount\', \'UA-37068666-1\']);\n  _gaq.push([\'_trackPageview\']);\n\n  (function() {\n    var ga = document.createElement(\'script\'); ga.type = \'text/javascript\'; ga.async = true;\n    ga.src = (\'https:\' == document.location.protocol ? \'https://ssl\' : \'http://www\') + \'.google-analytics.com/ga.js\';\n    var s = document.getElementsByTagName(\'script\')[0]; s.parentNode.insertBefore(ga, s);\n  })();\n\n</script>\n<!-- Yandex.Metrika counter -->\n<script type=\"text/javascript\">\n(function (d, w, c) {\n    (w[c] = w[c] || []).push(function() {\n        try {\n            w.yaCounter18859432 = new Ya.Metrika({id:18859432,\n                    clickmap:true,\n                    trackLinks:true,\n                    accurateTrackBounce:true});\n        } catch(e) { }\n    });\n\n    var n = d.getElementsByTagName(\"script\")[0],\n        s = d.createElement(\"script\"),\n        f = function () { n.parentNode.insertBefore(s, n); };\n    s.type = \"text/javascript\";\n    s.async = true;\n    s.src = (d.location.protocol == \"https:\" ? \"https:\" : \"http:\") + \"//mc.yandex.ru/metrika/watch.js\";\n\n    if (w.opera == \"[object Opera]\") {\n        d.addEventListener(\"DOMContentLoaded\", f, false);\n    }